import React, { useState } from 'react';
import CameraScanner from './CameraScanner';
import RiskMeter from './RiskMeter';
import Tesseract from 'tesseract.js';
import './style.css';

function App() {

  const [capturedImage, setCapturedImage] = useState("");
  const [ocrText, setOcrText] = useState("");

  const handleCapture = async (image) => {

    console.log("Image received:", image);

    setCapturedImage(image);

    try {

      const result = await Tesseract.recognize(
        image,
        "eng"
      );

      console.log(
        "OCR Extracted Text:",
        result.data.text
      );

      setOcrText(result.data.text);

    } catch(error){

      console.log(
        "OCR Error:",
        error
      );
    }
  };

  return (
    <div className="app">

      <header className="hero">
        <h1><b>SAFE BITE</b></h1>

        <p>
          Scan food ingredients and detect harmful additives instantly.
        </p>

      </header>

      <div className="main-container">

        <div className="left-side">

          <CameraScanner
            onCapture={handleCapture}
          />

          {capturedImage && (

            <div className="card">

              <h2>Captured Image</h2>

              <img
                src={capturedImage}
                alt="captured"
                width="100%"
              />

            </div>
          )}

          <div className="card">

            <h2>OCR Result</h2>

            <p>

              {ocrText
                ? ocrText
                : "No text detected yet..."}

            </p>

          </div>

        </div>

        <div className="right-side">

          <div className="card">

            <h2>Food Risk Meter</h2>

            <RiskMeter score={0} />

          </div>

          <div className="card">

            <h2>Detected Additives</h2>

            {[

              {
                ins: 'INS 102',
                name: 'Tartrazine',
                type: 'Artificial Color',
                risk: 'Moderate Risk',
              },

              {
                ins: 'INS 211',
                name: 'Sodium Benzoate',
                type: 'Preservative',
                risk: 'High Risk',
              }

            ].map((item, index) => (

              <div
                className="ingredient-card"
                key={index}
              >

                <div className="ingredient-top">

                  <h3>{item.ins}</h3>

                  <span className="risk-badge">

                    {item.risk}

                  </span>

                </div>

                <p>
                  <strong>Name:</strong>
                  {" "}
                  {item.name}
                </p>

                <p>
                  <strong>Type:</strong>
                  {" "}
                  {item.type}
                </p>

              </div>

            ))}

          </div>

        </div>

      </div>

    </div>
  );
}

export default App;
